import json,glob
want={'10.1145/3815425','10.1145/3769082','10.1109/tse.2024.3423712','10.1145/3744916.3787830','10.1007/978-3-031-98208-8_15','10.48550/arxiv.2505.19828','10.1109/access.2025.3635168','10.48550/arxiv.2512.10485','10.1007/s10207-026-01282-6','10.3390/bdcc10090303','10.1145/3832783.3834640','10.48550/arxiv.2412.15004'}
seen=set()
for f in sorted(glob.glob('*.json')):
    d=json.load(open(f))
    recs=d['results'] if isinstance(d,dict) and 'results' in d else d
    for r in recs:
        doi=(r.get('doi') or '').lower()
        if any(doi.startswith(w[:30]) for w in want) and doi not in seen:
            seen.add(doi); print(doi, '|', r.get('title'), '|', r.get('venue'), r.get('year')); print('  ', (r.get('abstract') or '')[:700]); print()
EOF

